<?php
namespace App\Http\Controllers;use App\Models\GoalType;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class GoalTypeController extends Controller{public function index(Request $r){$q=GoalType::latest();$q->when($r->search,fn($q,$v)=>$q->where(fn($x)=>$x->where('name','like',"%$v%")->orWhere('description','like',"%$v%")))->when($r->status!==null&&$r->status!=='',fn($q)=>$q->where('status',$r->status));return view('goal-types.index',['types'=>$q->paginate(10)->withQueryString()]);}public function store(Request $r){GoalType::create($this->data($r));return back()->with('success','Goal type created successfully.');}public function update(Request $r,GoalType $goalType){$goalType->update($this->data($r,$goalType->id));return back()->with('success','Goal type updated successfully.');}public function destroy(GoalType $goalType){$goalType->delete();return back()->with('success','Goal type deleted successfully.');}private function data(Request $r,$id=null){return $r->validate(['name'=>['required','string','min:2','max:191',Rule::unique('goal_types')->ignore($id)],'description'=>'nullable|string|max:1000','status'=>'required|boolean']);}}
